// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title OAuthRedirectRegistry
 * @notice On-chain registry for OAuth2 redirect URI validation
 * @dev Used by Kubernetes-deployed authorization server to validate redirect_uri parameters
 *      The K8s ingress controller queries this contract via eth_call before issuing tokens
 */
contract OAuthRedirectRegistry is Ownable {
    using ECDSA for bytes32;
    using Strings for uint256;

    struct ClientApp {
        address owner;
        bytes32 domainHash;
        string[] allowedRedirectPrefixes;
        bool active;
        uint256 registeredAt;
    }

    mapping(bytes32 => ClientApp) public clients;
    mapping(address => bytes32[]) public ownerClients;

    // Nonce tracking for replay protection
    mapping(bytes32 => mapping(uint256 => bool)) public usedNonces;

    event ClientRegistered(bytes32 indexed clientId, address indexed owner);
    event RedirectValidated(bytes32 indexed clientId, string redirectUri);
    event ClientDeactivated(bytes32 indexed clientId);

    uint256 private constant MAX_URI_LENGTH = 2048;
    uint256 private constant MAX_PREFIX_COUNT = 10;

    constructor() Ownable() {}

    function registerClient(
        string calldata domain,
        string[] calldata redirectPrefixes
    ) external returns (bytes32 clientId) {
        require(redirectPrefixes.length > 0 && redirectPrefixes.length <= MAX_PREFIX_COUNT, "Invalid prefix count");
        require(bytes(domain).length > 0, "Empty domain");

        clientId = keccak256(abi.encodePacked(msg.sender, domain, block.timestamp));
        require(clients[clientId].owner == address(0), "Client exists");

        bytes32 domainHash = keccak256(bytes(domain));

        clients[clientId] = ClientApp({
            owner: msg.sender,
            domainHash: domainHash,
            allowedRedirectPrefixes: new string[](0),
            active: true,
            registeredAt: block.timestamp
        });

        for (uint i = 0; i < redirectPrefixes.length; i++) {
            require(bytes(redirectPrefixes[i]).length > 0, "Empty prefix");
            require(_isValidScheme(redirectPrefixes[i]), "Invalid scheme");
            clients[clientId].allowedRedirectPrefixes.push(redirectPrefixes[i]);
        }

        ownerClients[msg.sender].push(clientId);
        emit ClientRegistered(clientId, msg.sender);
    }

    /**
     * @notice Validates a redirect URI against registered prefixes
     * @dev Called by K8s ingress via eth_call - this is the critical security gate
     * @param clientId The OAuth client identifier
     * @param redirectUri The redirect_uri parameter from the authorization request
     * @param nonce Anti-replay nonce from the authorization server
     * @param signature EIP-712 signature from the authorization server
     */
    function validateRedirect(
        bytes32 clientId,
        string calldata redirectUri,
        uint256 nonce,
        bytes calldata signature
    ) external view returns (bool) {
        ClientApp storage client = clients[clientId];
        require(client.active, "Client inactive");
        require(bytes(redirectUri).length <= MAX_URI_LENGTH, "URI too long");
        require(bytes(redirectUri).length > 8, "URI too short");

        // Verify the authorization server signed this validation request
        bytes32 messageHash = keccak256(abi.encodePacked(clientId, redirectUri, nonce));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(signature);
        require(signer == owner(), "Invalid signature");

        // Core redirect URI validation
        return _matchesAllowedPrefix(client.allowedRedirectPrefixes, redirectUri);
    }

    /**
     * @dev Checks if redirectUri starts with any allowed prefix
     *      Uses byte-level comparison for security
     */
    function _matchesAllowedPrefix(
        string[] storage allowedPrefixes,
        string calldata redirectUri
    ) internal view returns (bool) {
        bytes memory uriBytes = bytes(redirectUri);

        for (uint i = 0; i < allowedPrefixes.length; i++) {
            bytes memory prefixBytes = bytes(allowedPrefixes[i]);

            if (uriBytes.length < prefixBytes.length) continue;

            bool matches = true;
            for (uint j = 0; j < prefixBytes.length; j++) {
                // Case-insensitive comparison for scheme and host portion
                bytes1 a = _toLower(uriBytes[j]);
                bytes1 b = _toLower(prefixBytes[j]);
                if (a != b) {
                    matches = false;
                    break;
                }
            }

            if (matches) {
                // Verify the character after prefix is a valid path separator or end
                if (uriBytes.length == prefixBytes.length) return true;
                bytes1 nextChar = uriBytes[prefixBytes.length];
                // Only allow path continuation with slash
                if (nextChar == 0x2F) {
                    return true;
                }
            }
        }
        return false;
    }

    function _toLower(bytes1 b) internal pure returns (bytes1) {
        if (b >= 0x41 && b <= 0x5A) {
            return bytes1(uint8(b) + 32);
        }
        return b;
    }

    function _isValidScheme(string calldata uri) internal pure returns (bool) {
        bytes memory b = bytes(uri);
        if (b.length < 8) return false;
        // Must start with https://
        return (b[0] == 0x68 && b[1] == 0x74 && b[2] == 0x74 && b[3] == 0x70 &&
                b[4] == 0x73 && b[5] == 0x3A && b[6] == 0x2F && b[7] == 0x2F);
    }

    function deactivateClient(bytes32 clientId) external {
        require(clients[clientId].owner == msg.sender || msg.sender == owner(), "Unauthorized");
        clients[clientId].active = false;
        emit ClientDeactivated(clientId);
    }

    function getClientPrefixes(bytes32 clientId) external view returns (string[] memory) {
        return clients[clientId].allowedRedirectPrefixes;
    }
}
